#!/usr/bin/env bash
#
# scripts/accept-setup.sh: set up acceptance on the Test account (ADR-0009):
# the two accounts, the Acceptance app, the Cloud password, the Driver's and
# the Peer's first logins, the fixtures, and the GitHub environment
# `acceptance` for CI. Re-run any time: every step offers to keep what is done.
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# The harness's own file (acceptance/src/config.rs reads the same path).
accept_file() {
  if [[ -n "${TG_ACCEPT_FILE:-}" ]]; then printf '%s' "$TG_ACCEPT_FILE"
  else printf '%s/tg-mcp-accept/env' "${XDG_CONFIG_HOME:-$HOME/.config}"; fi
}

# done_key KEY: KEY already has a value in the file.
done_key() { [[ -n "$(_existing "$1" || true)" ]]; }

# set_env_secret NAME: copies NAME from the file into the GitHub environment
# `acceptance`, piped so it never shows on screen or in shell history.
set_env_secret() {
  local name="$1" value
  value=$(_existing "$name" || true)
  if [[ -z "$value" ]]; then
    SKIPPED+=("GitHub secret $name: no value in $ENV_FILE yet")
    warn "skipped $name: no value yet"; return
  fi
  if printf '%s' "$value" | gh secret set "$name" --env acceptance >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s %s in the environment acceptance\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("GitHub secret $name (gh secret set $name --env acceptance)")
    warn "couldn't set $name"
  fi
}

run_wizard() {

TOTAL_STAGES=8
ENV_FILE=$(accept_file)
mkdir -p "$(dirname "$ENV_FILE")" && chmod 700 "$(dirname "$ENV_FILE")"
cd "$(git rev-parse --show-toplevel)"

banner "tg-mcp acceptance: Test account, Peer and CI"

stage "Two Telegram accounts"
say "Acceptance runs on a Test account that holds nothing of value, and a Peer that"
say "plays the other side of its chats (GLOSSARY → Acceptance). Never your own account."
step "Put two SIMs in phones and create a Telegram account on each, in the official app."
step "On each account: Settings → Username: set one (the fixtures find each other by it)."
step "Peer: Settings → Privacy and Security → Two-Step Verification stays OFF."
note "New accounts are watched for spam by Telegram: use them like a person for a day first."
pause "Both accounts exist and have usernames? Press Enter"

stage "The Acceptance app"
say "A Telegram app of its own, on the Test account's number: if Telegram limits it,"
say "production's app and the Built-in app are untouched (ADR-0007, ADR-0009)."
open_url "https://my.telegram.org/apps"
step "Log in with the Test account's phone number (the code arrives in Telegram)."
step "API development tools → create an application (title e.g. 'tg-mcp acceptance')."
step "Copy App api_id and App api_hash."
ask TG_ACCEPT_API_ID "App api_id:"
ask_secret TG_ACCEPT_API_HASH "App api_hash (hidden):"
write_env TG_ACCEPT_API_ID "$TG_ACCEPT_API_ID"
write_env TG_ACCEPT_API_HASH "$TG_ACCEPT_API_HASH"

stage "The Test account's Cloud password"
say "Every run types it on the login page, so two-step verification is always checked."
step "Test account: Settings → Privacy and Security → Two-Step Verification → set a password."
ask_secret TG_ACCEPT_CLOUD_PASSWORD "That password (hidden):"
write_env TG_ACCEPT_CLOUD_PASSWORD "$TG_ACCEPT_CLOUD_PASSWORD"

stage "The Driver: the harness's login to the Test account"
say "It stands in for your phone: it accepts QR logins and reads what Telegram holds."
if done_key TG_ACCEPT_DRIVER_SESSION && ! confirm "The Driver is logged in already. Log in again?"; then
  note "kept the Driver's login"
else
  step "Have the Test account's phone at hand: Telegram sends the code there."
  cargo accept sign-in driver
fi
pause "Press Enter to continue"

stage "The Peer's login"
if done_key TG_ACCEPT_PEER_SESSION && ! confirm "The Peer is logged in already. Log in again?"; then
  note "kept the Peer's login"
else
  step "Have the Peer's phone at hand: Telegram sends the code there."
  cargo accept sign-in peer
fi
pause "Press Enter to continue"

stage "The fixtures"
say "The test chats: A (with the Peer), B, a forum with Releases, G (👍 only), folder Work."
say "Made or repaired on the Test account; a second run changes nothing."
cargo accept fixtures || warn "fixtures failed: read the message above, fix it, re-run this wizard"
pause "Press Enter to continue"

stage "A first run"
say "Logs the Test account (QR, Cloud password, Consent) and the Peer into a local server."
note "The first time builds the server: a few minutes."
if cargo accept login login-peer; then
  note "PASS: acceptance works on this machine."
else
  warn "not PASS: read the report above (BLOCKED means Telegram limited an account)."
fi
pause "Press Enter to continue"

stage "CI: the GitHub environment acceptance"
say "Cloud agent sessions run acceptance in GitHub Actions; the smoke after each"
say "deploy does too. Both read these secrets from the environment 'acceptance'."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  SKIPPED+=("the GitHub environment acceptance: install gh, gh auth login, re-run")
  warn "gh isn't ready: skipping CI"
elif confirm "Create or update the environment acceptance with the Test account's secrets?"; then
  repo=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
  gh api -X PUT "repos/$repo/environments/acceptance" >/dev/null \
    && printf '  %s✓%s environment acceptance\n' "$GREEN" "$RESET"
  for name in TG_ACCEPT_API_ID TG_ACCEPT_API_HASH TG_ACCEPT_ACCOUNT_ID TG_ACCEPT_PEER_ID \
              TG_ACCEPT_CLOUD_PASSWORD TG_ACCEPT_DRIVER_SESSION TG_ACCEPT_PEER_SESSION; do
    set_env_secret "$name"
  done
  if confirm "Run the smoke against production after every deploy (ACCEPTANCE_SMOKE=on)?"; then
    set_var ACCEPTANCE_SMOKE on
  fi
fi

finish
note "Run a scenario: cargo accept <id>   (cargo accept --list)"
}

run_wizard "$@"; exit
